// @MappedSuperclass: shared audit fields. NOT an entity — no table.
// @PrePersist/@PreUpdate: auto-stamp timestamps without repeating in every service
package com.bank.fd.model;

import jakarta.persistence.*;
import org.springframework.data.annotation.*;
import java.time.LocalDateTime;

@MappedSuperclass
public abstract class BaseAuditEntity {

    @CreatedDate                    // Spring Data JPA auditing
    @Column(name = "created_at", updatable = false)
    private LocalDateTime createdAt;

    @LastModifiedDate               // auto-updated on every save
    @Column(name = "updated_at")
    private LocalDateTime updatedAt;

    @CreatedBy                      // set by AuditorAware bean
    @Column(name = "created_by", updatable = false)
    private String createdBy;

    @LastModifiedBy
    @Column(name = "modified_by")
    private String modifiedBy;

    // Fallback: lifecycle callbacks (work without @EnableJpaAuditing)
    @PrePersist
    void onCreate() {
        if (createdAt == null) createdAt = LocalDateTime.now();
        updatedAt = LocalDateTime.now();
    }

    @PreUpdate
    void onUpdate() { updatedAt = LocalDateTime.now(); }

    public LocalDateTime getCreatedAt() { return createdAt; }
    public LocalDateTime getUpdatedAt() { return updatedAt; }
    public String getCreatedBy() { return createdBy; }
}
