package com.bank.fd.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.math.RoundingMode;

@Entity
@Table(name = "fixed_deposits")
public class FixedDeposit extends BaseAuditEntity {

    @Id
    @Column(name = "fd_id")
    private String fdId;

    @Column(name = "account_id", nullable = false)
    private String accountId;

    @Column(nullable = false)
    private BigDecimal principal;

    @Column(name = "interest_rate", nullable = false)
    private BigDecimal interestRate;

    @Column(name = "tenure_months", nullable = false)
    private int tenureMonths;

    @Column(name = "maturity_amount", nullable = false)
    private BigDecimal maturityAmount;

    @Column(nullable = false)
    private String status;

    @Version  // OPTIMISTIC LOCKING: auto-incremented on UPDATE
    private Long version;

    protected FixedDeposit() {}

    public FixedDeposit(String fdId, String accountId, BigDecimal principal,
                         BigDecimal interestRate, int tenureMonths) {
        this.fdId = fdId;
        this.accountId = accountId;
        this.principal = principal;
        this.interestRate = interestRate;
        this.tenureMonths = tenureMonths;
        this.maturityAmount = calculateMaturity(principal, interestRate, tenureMonths);
        this.status = "ACTIVE";
        // ENTITY STATE: TRANSIENT (new object, not in persistence context)
    }

    private BigDecimal calculateMaturity(BigDecimal p, BigDecimal rate, int months) {
        BigDecimal years = BigDecimal.valueOf(months).divide(BigDecimal.valueOf(12), 4, RoundingMode.HALF_UP);
        return p.add(p.multiply(rate).multiply(years).divide(new BigDecimal("100"), 2, RoundingMode.HALF_UP));
    }

    public void prematureClose() {
        this.status = "PREMATURELY_CLOSED";
        // Penalty: reduce maturity amount by 1%
        this.maturityAmount = maturityAmount.multiply(new BigDecimal("0.99")).setScale(2, RoundingMode.HALF_UP);
    }

    public void renew(BigDecimal newRate, int newTenure) {
        this.principal = this.maturityAmount;
        this.interestRate = newRate;
        this.tenureMonths = newTenure;
        this.maturityAmount = calculateMaturity(principal, newRate, newTenure);
        this.status = "RENEWED";
    }

    public String getFdId() { return fdId; }
    public String getAccountId() { return accountId; }
    public BigDecimal getPrincipal() { return principal; }
    public BigDecimal getInterestRate() { return interestRate; }
    public int getTenureMonths() { return tenureMonths; }
    public BigDecimal getMaturityAmount() { return maturityAmount; }
    public String getStatus() { return status; }
    public Long getVersion() { return version; }
}
