package com.bank.fd.repository;

import com.bank.fd.model.FixedDeposit;
import org.springframework.data.domain.*;
import org.springframework.data.jpa.repository.*;
import jakarta.persistence.LockModeType;
import java.util.List;
import java.util.Optional;

public interface FixedDepositRepository extends JpaRepository<FixedDeposit, String> {

    // PESSIMISTIC LOCK: for concurrent premature closure
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("SELECT fd FROM FixedDeposit fd WHERE fd.fdId = :id")
    Optional<FixedDeposit> findByIdForUpdate(String id);

    // Offset pagination (simple but slow on page 10000)
    Page<FixedDeposit> findByAccountId(String accountId, Pageable pageable);

    // KEYSET pagination (fast even on page 10000)
    @Query("SELECT fd FROM FixedDeposit fd WHERE fd.accountId = :accountId AND fd.fdId > :lastId ORDER BY fd.fdId")
    List<FixedDeposit> findNextPage(String accountId, String lastId, Pageable pageable);

    // First page (no cursor yet)
    @Query("SELECT fd FROM FixedDeposit fd WHERE fd.accountId = :accountId ORDER BY fd.fdId")
    List<FixedDeposit> findFirstPage(String accountId, Pageable pageable);
}
