package com.bank.fd.service;

import com.bank.fd.dto.*;
import com.bank.fd.model.FixedDeposit;
import com.bank.fd.repository.FixedDepositRepository;
import jakarta.persistence.EntityManager;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.domain.*;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Retryable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.List;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class FdService {

    private final FixedDepositRepository fdRepo;
    private final EntityManager em;

    // ═══ ENTITY LIFECYCLE DEMO ═══
    @Transactional
    public FdResponse createFd(FdRequest request) {
        String fdId = "FD-" + UUID.randomUUID().toString().substring(0, 6).toUpperCase();

        // STATE 1: TRANSIENT (new object — not managed)
        FixedDeposit fd = new FixedDeposit(fdId, request.accountId(), request.principal(),
            request.interestRate(), request.tenureMonths());
        log.info("[LIFECYCLE] State: TRANSIENT (new object)");

        // STATE 2: MANAGED (after persist — tracked by persistence context)
        em.persist(fd);
        log.info("[LIFECYCLE] State: MANAGED (after persist — INSERT queued)");

        // Changes are AUTO-DETECTED (dirty checking):
        // fd.setXxx() → Hibernate detects change → UPDATE on flush
        log.info("[LIFECYCLE] FD {} created. @PrePersist auto-stamped createdAt.", fdId);
        return FdResponse.from(fd);
    }

    // ═══ DETACH + MERGE ═══
    @Transactional
    public FdResponse renewFd(String fdId, BigDecimal newRate, int newTenure) {
        FixedDeposit fd = fdRepo.findById(fdId).orElseThrow(); // MANAGED
        em.detach(fd);  // STATE 3: DETACHED (disconnected — changes NOT tracked)
        log.info("[LIFECYCLE] State: DETACHED (after detach)");

        fd.renew(newRate, newTenure);  // change on detached entity — NOT auto-flushed!
        log.info("[LIFECYCLE] Changed detached entity — NOT auto-synced to DB");

        // merge(): copies detached state into persistence context → returns MANAGED copy
        FixedDeposit managedFd = em.merge(fd);  // STATE 2: back to MANAGED
        log.info("[LIFECYCLE] State: MANAGED (after merge — UPDATE queued)");
        return FdResponse.from(managedFd);
    }

    // ═══ OPTIMISTIC LOCK + RETRY ═══
    @Retryable(retryFor = ObjectOptimisticLockingFailureException.class,
               maxAttempts = 3, backoff = @Backoff(delay = 100, multiplier = 2))
    @Transactional
    public FdResponse prematureCloseOptimistic(String fdId) {
        FixedDeposit fd = fdRepo.findById(fdId).orElseThrow();
        log.info("[OPTIMISTIC] Version={} — closing FD {}", fd.getVersion(), fdId);
        fd.prematureClose();
        fdRepo.save(fd);
        // Hibernate: UPDATE ... SET status='CLOSED', version=version+1 WHERE fd_id=? AND version=?
        // If another TX changed version → OptimisticLockException → @Retryable retries
        return FdResponse.from(fd);
    }

    // ═══ PESSIMISTIC LOCK ═══
    @Transactional
    public FdResponse prematureClosePessimistic(String fdId) {
        FixedDeposit fd = fdRepo.findByIdForUpdate(fdId).orElseThrow();
        // SQL: SELECT ... FOR UPDATE → row LOCKED, other TX waits
        log.info("[PESSIMISTIC] Row locked — closing FD {}", fdId);
        fd.prematureClose();
        fdRepo.save(fd);
        return FdResponse.from(fd);
    }

    // ═══ KEYSET PAGINATION (fast for deep pages) ═══
    @Transactional(readOnly = true)
    public PageResult<FdResponse> listFds(String accountId, String afterCursor, int size) {
        List<FixedDeposit> results;
        if (afterCursor == null || afterCursor.isBlank()) {
            results = fdRepo.findFirstPage(accountId, PageRequest.of(0, size + 1));
        } else {
            results = fdRepo.findNextPage(accountId, afterCursor, PageRequest.of(0, size + 1));
        }

        boolean hasMore = results.size() > size;
        List<FixedDeposit> page = hasMore ? results.subList(0, size) : results;
        String nextCursor = hasMore ? page.getLast().getFdId() : null;

        return new PageResult<>(page.stream().map(FdResponse::from).toList(),
            page.size(), nextCursor, hasMore);
    }
}
