package com.bank.fd.controller;

import com.bank.fd.dto.*;
import com.bank.fd.service.FdService;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/fd")
@RequiredArgsConstructor
public class FdController {

    private final FdService fdService;

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public FdResponse create(@RequestBody @Valid FdRequest request) {
        return fdService.createFd(request);
    }

    @PutMapping("/{fdId}/renew")
    public FdResponse renew(@PathVariable String fdId,
                             @RequestParam java.math.BigDecimal newRate, @RequestParam int newTenure) {
        return fdService.renewFd(fdId, newRate, newTenure);
    }

    @PutMapping("/{fdId}/close-optimistic")
    public FdResponse closeOptimistic(@PathVariable String fdId) {
        return fdService.prematureCloseOptimistic(fdId);
    }

    @PutMapping("/{fdId}/close-pessimistic")
    public FdResponse closePessimistic(@PathVariable String fdId) {
        return fdService.prematureClosePessimistic(fdId);
    }

    @GetMapping("/account/{accountId}")
    public PageResult<FdResponse> list(@PathVariable String accountId,
                                        @RequestParam(required = false) String after,
                                        @RequestParam(defaultValue = "3") int size) {
        return fdService.listFds(accountId, after, size);
    }
}
